import{_ as s,c as n,o as t,j as o,Y as r,t as i}from"./chunks/framework.BNTND4LZ.js";const _=JSON.parse('{"title":"uts_namespaces | x-cmd man (man7) | overview of Linux UTS namespaces","titleTemplate":false,"description":"x-cmd man (man7 Manual Page) | uts_namespaces - overview of Linux UTS namespaces","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"uts_namespaces | x-cmd man (man7) | overview of Linux UTS namespaces"}],["meta",{"name":"og:description","content":"x-cmd man (man7 Manual Page) | uts_namespaces - overview of Linux UTS namespaces"}]]},"headers":[],"params":{"isMan":true,"man":"uts_namespaces","category":"man7","desc":"overview of Linux UTS namespaces"},"relativePath":"man7/uts_namespaces.md","filePath":"man7/[man].md"}'),m={name:"man7/uts_namespaces.md"},c={class:"visually-hidden"};function p(a,e,g,d,h,l){return t(),n("div",null,[o("h1",c,i(a.$params.man),1),e[0]||(e[0]=r('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>uts_namespaces - overview of Linux UTS namespaces</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>UTS namespaces provide isolation of two system identifiers: the hostname and the NIS domain name. These identifiers are set using <strong>sethostname</strong>(2) and <strong>setdomainname</strong>(2), and can be retrieved using <strong>uname</strong>(2), <strong>gethostname</strong>(2), and <strong>getdomainname</strong>(2). Changes made to these identifiers are visible to all other processes in the same UTS namespace, but are not visible to processes in other UTS namespaces.</p><p>When a process creates a new UTS namespace using <strong>clone</strong>(2) or <strong>unshare</strong>(2) with the <strong>CLONE_NEWUTS</strong> flag, the hostname and domain name of the new UTS namespace are copied from the corresponding values in the caller&#39;s UTS namespace.</p><p>Use of UTS namespaces requires a kernel that is configured with the <strong>CONFIG_UTS_NS</strong> option.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>nsenter</strong>(1), <strong>unshare</strong>(1), <strong>clone</strong>(2), <strong>getdomainname</strong>(2), <strong>gethostname</strong>(2), <strong>setns</strong>(2), <strong>uname</strong>(2), <strong>unshare</strong>(2), <strong>namespaces</strong>(7)</p>',8))])}const S=s(m,[["render",p]]);export{_ as __pageData,S as default};
